import { block, prism } from './shatter-lab-solid.js';

export function makeChandelierStage() {
  const solids = [],
    put = (faces, name) => solids.push({ faces, name });
  put(block(-2.85, 0, 0.7, 0.16, 0.7), '連鎖・高架の足');
  put(block(-2.85, 0.16, 0.28, 5.09, 0.3), '連鎖・高架の柱');
  put(block(-2.01, 5.25, 1.96, 0.2, 0.3), '連鎖・高架の梁');
  put(block(-1.2, 4.8, 0.22, 0.45, 0.24, 0, 0.008), '連鎖・上の吊り首');
  put(
    prism(
      [
        [-1.8, 3.9],
        [-1.2, 3.5],
        [-0.6, 3.9],
        [-0.6, 4.5],
        [-1.06, 4.8],
        [-1.34, 4.8],
        [-1.8, 4.5],
      ],
      0.92,
    ),
    '連鎖・起点の大結晶',
  );
  put(block(2.25, 0, 0.65, 0.16, 0.65), '連鎖・受け腕の足');
  put(block(2.25, 0.16, 0.27, 2.44, 0.3), '連鎖・受け腕の柱');
  put(block(0.2, 2.6, 4.38, 0.24, 0.32, 0, 0.008), '連鎖・衝突を受ける長い腕');
  put(block(0.6, 2.26, 0.28, 0.34, 0.28, 0, 0.008), '連鎖・下の吊り首');
  put(block(0.6, 2.0, 2.6, 0.26, 0.72), '連鎖・下段の横梁');
  for (const [index, x] of [-0.2, 0.6, 1.4].entries()) {
    put(
      prism(
        [
          [x - 0.36, 1.12],
          [x, 0.74 + (index % 2) * 0.14],
          [x + 0.36, 1.12],
          [x + 0.36, 1.8],
          [x + 0.16, 2.0],
          [x - 0.16, 2.0],
          [x - 0.36, 1.8],
        ],
        0.82,
      ),
      `連鎖・下段の大結晶${index + 1}`,
    );
  }
  put(block(0.6, 0, 0.6, 0.16, 0.6, 1.25), '連鎖・控えの足');
  put(block(0.6, 0.16, 0.24, 2.26, 0.26, 1.25), '連鎖・控えの柱');
  put(block(0.6, 2.42, 0.24, 0.16, 1.26, 0.62, 0.008), '連鎖・控えの細い横腕');
  return {
    solids,
    viewElevation: 0.29,
    hint: '下段は長い受け腕と細い控え腕で支えられています。控え腕を弱め、上の結晶の落下を受け腕へつなごう。先に支えを両方断つと、別々の落下になります。',
  };
}
